"""Aggregate integration-test timings from CI pytest logs."""

from __future__ import annotations

import re
import sys
from pathlib import Path
from collections import defaultdict

S = Path(__file__).parent
MARKERS = ["smoke", "area_package", "area_install", "area_btrfs", "area_folder", "area_core"]

marker_map: dict[str, set[str]] = defaultdict(set)
for m in MARKERS:
    for line in (S / "markers" / f"{m}.txt").read_text().splitlines():
        marker_map[line.strip()].add(m)
all_tests = [ln.strip() for ln in (S / "markers" / "all.txt").read_text().splitlines()]

END = re.compile(r"^\[it \d\d:\d\d:\d\d\] END\s+(\S+) \((\d+\.\d+)s\)")
DUR = re.compile(r"^(\d+\.\d+)s (setup|call|teardown)\s+(\S+)")


def parse(path: Path):
    per_test: dict[str, float] = {}
    phases: list[tuple[float, str, str]] = []
    total = None
    for line in path.read_text(errors="replace").splitlines():
        m = END.match(line)
        if m:
            per_test[m.group(1)] = float(m.group(2))
        d = DUR.match(line)
        if d:
            phases.append((float(d.group(1)), d.group(2), d.group(3)))
        t = re.search(r"passed.* in (\d+\.\d+)s", line)
        if t:
            total = float(t.group(1))
    return per_test, phases, total


runs = sorted((S / "runs").glob("*/pytest-output.log"))
data = {}
for p in runs:
    per_test, phases, total = parse(p)
    if len(per_test) < 60:
        continue
    data[p.parent.name] = (per_test, phases, total)

print(f"runs analysed: {list(data)}\n")

# median per test across runs of the CURRENT suite (tests present in markers/all.txt)
by_test: dict[str, list[float]] = defaultdict(list)
for per_test, _, _ in data.values():
    for nodeid, secs in per_test.items():
        by_test[nodeid].append(secs)


def med(xs: list[float]) -> float:
    xs = sorted(xs)
    n = len(xs)
    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2


current = {t: med(by_test[t]) for t in all_tests if t in by_test}
missing = [t for t in all_tests if t not in by_test]
print(f"tests mapped: {len(current)}/{len(all_tests)}; unmatched: {missing}\n")

grand = sum(current.values())
print(f"sum of per-test wall clock (median across runs): {grand:.0f}s ({grand/60:.1f} min)\n")

print("== per module ==")
mod: dict[str, list[float]] = defaultdict(list)
for t, s in current.items():
    mod[t.split("::")[0]].append(s)
for m, xs in sorted(mod.items(), key=lambda kv: -sum(kv[1])):
    print(f"{sum(xs):7.0f}s  {len(xs):3d} tests  {sum(xs)/grand*100:4.1f}%  {m}")

print("\n== per CI selection (marker expression) ==")


def sel_total(pred) -> tuple[float, int]:
    xs = [s for t, s in current.items() if pred(t)]
    return sum(xs), len(xs)


rows = [("full", lambda t: True), ("smoke", lambda t: "smoke" in marker_map[t])]
for a in MARKERS[1:]:
    rows.append((f"smoke or {a}", lambda t, a=a: marker_map[t] & {"smoke", a}))
    rows.append((f"  {a} alone", lambda t, a=a: a in marker_map[t]))
for name, pred in rows:
    tot, n = sel_total(pred)
    print(f"{tot:7.0f}s ({tot/60:5.1f} min)  {n:3d} tests  {name}")

print("\n== slowest tests (median) ==")
for t, s in sorted(current.items(), key=lambda kv: -kv[1])[:20]:
    areas = ",".join(sorted(marker_map[t])) or "-"
    print(f"{s:7.1f}s  [{areas}]  {t}")

print("\n== setup vs call (from --durations tables, summed over runs) ==")
ph: dict[str, float] = defaultdict(float)
for _, phases, _ in data.values():
    for secs, phase, _n in phases:
        ph[phase] += secs
tot = sum(ph.values())
for phase, secs in sorted(ph.items(), key=lambda kv: -kv[1]):
    print(f"{secs:8.0f}s  {secs/tot*100:4.1f}%  {phase} (top-25 entries only)")

print("\n== per run totals ==")
for name, (per_test, _, total) in data.items():
    s = sum(per_test.values())
    print(f"{name}: {len(per_test)} tests, session {total:.0f}s, sum-of-tests {s:.0f}s, gap {total - s:.0f}s")

